function standardizeURL(urlString) {

            if(!urlString){
              return urlString
            }

            let urlStr = urlString.trim();
            // 1. Ensure a protocol exists, defaulting to http.
            if (!/^(?:f|ht)tps?:\/\//i.test(urlStr)) {
                urlStr = 'http://' + urlStr;
            }

            try {
                // Manually parse the URL using a regular expression.
                // Groups: 1:protocol, 2:hostname, 3:port, 4:pathname, 5:query, 6:hash
                const urlRegex = /^((?:https?|ftp):)\/\/([^:\/\?#]+)(?::(\d+))?(\/[^?#]*)?(\?[^#]*)?(#.*)?$/i;
                const matches = urlStr.match(urlRegex);

                if (!matches) {
                    throw new Error("Invalid URL structure");
                }

                let protocol = matches[1].toLowerCase();
                let hostname = matches[2].toLowerCase();
                let port = matches[3] || '';
                let pathname = matches[4] || '/';
                let query = matches[5] || '';
                // Hash (matches[6]) is ignored intentionally.

                // 3. Remove default ports.
                if ((protocol === 'http:' && port === '80') ||
                    (protocol === 'https:' && port === '443')) {
                    port = '';
                }

                // 5. Remove trailing slash from the pathname if it's not just "/".
                if (pathname.length > 1 && pathname.endsWith('/')) {
                    pathname = pathname.slice(0, -1);
                }

                // 7. Decode pathname to normalize encoding (e.g., %2D -> -), then re-encode.
                pathname = encodeURI(decodeURIComponent(pathname));

                // 6. Sort query parameters alphabetically.
                if (query) {
                    // Remove leading '?' to get the search string
                    const searchString = query.substring(1);

                    if (searchString) {
                        const params = searchString.split('&')
                            .map(p => {
                                const parts = p.split('=');
                                // Decode key and value, handling cases like "?a" where value is missing
                                const key = decodeURIComponent(parts[0] || '');
                                const value = decodeURIComponent(parts.slice(1).join('=') || '');
                                return { key, value };
                            })
                            .filter(p => p.key); // Ensure key is not empty

                        // Sort by key
                        params.sort((a, b) => a.key.localeCompare(b.key));

                        // Rebuild the query string, re-encoding components
                        query = '?' + params
                            .map(p => `${encodeURIComponent(p.key)}=${encodeURIComponent(p.value)}`)
                            .join('&');
                    } else {
                        query = ''; // Handle cases like "example.com?"
                    }
                }

